function phero(r){return '<section class="phero" style="--pg-bg:'+r.bg+';--pg-fg:'+r.fg+'"><div class="wrap"><span class="sticker">'+r.eyebrow+' of 10</span><h1>'+r.title+'</h1><p class="tagline">'+r.tag+'</p><span class="hand">'+r.hand+'</span>'+stk(r.stk[0],'deco d1 bob','right:2%;top:-4px;--s:120px;--r:10deg')+stk(r.stk[1],'deco d2','right:170px;bottom:-18px;--s:84px;--r:-12deg')+'</div></section>'}
function pager(id){var i=ROUTES.findIndex(function(x){return x.id===id}),n=ROUTES[(i+1)%ROUTES.length];return '<div class="pager"><a class="btn light" href="#home">← Home</a><a class="btn" href="#'+n.id+'">Next: '+n.label+' →</a></div>'}
