function related(id){var l=RELATED[id];if(!l)return '';return '<section class="related" aria-labelledby="rel-h"><h2 class="sub" id="rel-h">Keep exploring</h2><ul>'+l.map(function(k){var r=ROUTES.find(function(x){return x.id===k});return r?'<li><a href="#'+r.id+'"><strong>'+esc(r.label)+' →</strong><span>'+esc(r.blurb||r.tag)+'</span></a></li>':''}).join('')+'</ul></section>'}
function page(id,inner){var r=ROUTES.find(function(x){return x.id===id});return phero(r)+'<div class="wrap section">'+inner+related(id)+pager(id)+'</div>'}

