 function startPinch(){var a=pts(),r=mv.getBoundingClientRect(),cx=(a[0].x+a[1].x)/2-r.left,cy=(a[0].y+a[1].y)/2-r.top;pinch={d:Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)||1,z:st.z,ax:(cx-st.x)/st.z,ay:(cy-st.y)/st.z};drag=null}
