function initShop(){
 var grid=document.getElementById('shop-grid'),count=document.getElementById('shop-count'),filter='all';
 function render(){var now=istNow(),list=SHOPS.filter(function(s){return filter==='all'||s.group===filter});
  grid.innerHTML=list.map(function(s,i){var st=shopStatus(s,now);
   return '<article class="card shopcard popcard"'+(MPA?'':' role="button" tabindex="0" aria-haspopup="dialog"')+' data-t="shopping" data-n="'+SHOPS.indexOf(s)+'" data-i="'+SHOPS.indexOf(s)+'"><div class="pic">'+(s.img?'<img class="photo" src="'+s.img+'" alt="'+esc(s.imgAlt||s.name)+'" loading="lazy">':art(s.art,i,s.name))+'</div><div class="body"><div class="row-top"><span class="tag '+(s.tc||'t-sand')+'">'+esc(s.tag)+'</span>'+st+'</div><h3>'+(MPA?'<a class="cardlink" href="'+placeURL(s)+'">'+esc(s.name)+'</a>':esc(s.name))+'</h3><p class="meta">'+esc(s.area)+'</p><p class="tease">'+esc(s.text)+'</p><span class="peek">Tap for details →</span></div></article>'}).join('');
  fixLinks(grid);
  count.textContent='Showing '+list.length+' of '+SHOPS.length+' places'}
 document.getElementById('shop-filters').addEventListener('click',function(e){var b=e.target.closest('button[data-f]');if(!b)return;filter=b.getAttribute('data-f');document.querySelectorAll('#shop-filters button').forEach(function(x){x.setAttribute('aria-pressed',x===b?'true':'false')});render()});
 render()}
function initTip(){document.getElementById('tip-form').addEventListener('submit',function(e){e.preventDefault();var f=e.target,name=f.elements['name'].value.trim(),spot=f.elements['spot'].value.trim(),why=f.elements['why'].value.trim(),cat=f.elements['cat'].value,res=document.getElementById('tip-result'),btn=f.querySelector('button[type="submit"]');
 if(!spot){res.textContent='Add the place name and area first.';f.elements['spot'].focus();return}
 if(f.elements['company']&&f.elements['company'].value){res.textContent='Thanks for the tip.';f.reset();return}
 var body=new URLSearchParams();
 body.append('entry.387853459',name);body.append('entry.2071533458',cat);body.append('entry.1473352482',spot);body.append('entry.1623963818',why);
 btn.disabled=true;res.textContent='Sending your tip...';
 fetch('https://docs.google.com/forms/d/e/1FAIpQLSda03W5mucx_SlxR_BVemGwanIezPLhEU2I8R8RHyEIAbSktg/formResponse',{method:'POST',mode:'no-cors',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:body.toString()})
 .then(function(){res.textContent='Thanks'+(name?', '+name:'')+'. Your tip about '+spot+' was sent. We check every tip before anything goes on the site.';f.reset()})
 .catch(function(){res.textContent='Sorry, that did not send. Check your connection and try again.'})
 .then(function(){btn.disabled=false})})}

