function route(){closePop();var id=(location.hash||'#home').slice(1),jump=null;if(MPA){id=window.__ROUTE||'home';if(location.hash==='#map-section')jump='map-section'}else if(id==='map-section'){jump=id;id='home'}var r=ROUTES.find(function(x){return x.id===id})||ROUTES[0];
 document.documentElement.style.setProperty('--pagec',r.bg||'var(--teal)');document.documentElement.style.setProperty('--pagefg',r.fg||'var(--ink)');
 TAB={};curTab=r.id;app.innerHTML=PAGES[r.id]();
 menu.querySelectorAll('a').forEach(function(a){if(a.getAttribute('data-id')===r.id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 var act=menu.querySelector('[aria-current]');if(act&&act.scrollIntoView)try{act.scrollIntoView({inline:'center',block:'nearest'})}catch(e){}
 if(r.id==='plan')initPlan();if(r.id==='shopping')initShop();if(r.id==='food'){reg(FOOD);initFilter(FOOD)}if(r.id==='education'){reg(EDUALL);initFilter(EDUALL)}if(r.id==='gems'){reg(GEMS);initFilter(GEMS)}if(r.id==='tip')initTip();if(r.id==='home'){initMap();initTip()}
 if(MPA&&PLACE&&POPTABS.indexOf(r.id)>-1){var pi=popFind(r.id,PLACE);if(pi>-1)openPop(r.id,pi,document.querySelector('#app .popcard[data-t="'+r.id+'"][data-n="'+pi+'"]'),popDom(r.id),'keep')}
 fixLinks(document);window.scrollTo(0,0);if(jump){var el=document.getElementById(jump);if(el)el.scrollIntoView()}}
if(MPA){function legacy(){var lh=(location.hash||'').slice(1);if((window.__ROUTE||'home')==='home'&&lh&&lh!=='home'&&lh!=='map-section'&&ROUTES.some(function(x){return x.id===lh}))location.replace(routeURL(lh))}legacy();window.addEventListener('hashchange',legacy);
 window.addEventListener('popstate',function(){var t=window.__ROUTE;if(POPTABS.indexOf(t)<0)return;var m=location.pathname.replace(/\/+$/,'').split('/').pop(),i=popFind(t,m);if(i>-1)openPop(t,i,null,popDom(t),'keep');else{popPushed=false;removePop()}})}
else window.addEventListener('hashchange',route);
app.addEventListener('click',function(e){var l=e.target.closest('a');if(l&&(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||e.button))return;if(l&&!l.classList.contains('cardlink'))return;var c=e.target.closest('.popcard');if(!c)return;if(l)e.preventDefault();var t=c.getAttribute('data-t');openPop(t,+c.getAttribute('data-n'),c,popDom(t))});
app.addEventListener('keydown',function(e){if(e.key!=='Enter'&&e.key!==' ')return;var c=e.target.classList&&e.target.classList.contains('popcard')?e.target:null;if(c){e.preventDefault();var t=c.getAttribute('data-t');openPop(t,+c.getAttribute('data-n'),c,popDom(t))}});
window.__GC={SHOPS:SHOPS,ROUTES:ROUTES,slug:slug,getTAB:function(){return TAB},POPTABS:POPTABS};
